function QueueForgePure(){
  function ok(v){ return typeof v === 'number' && isFinite(v); }
  function num(v){ var n = Number(v); return isFinite(n) ? n : NaN; }

  // ==================== Little 定律：L = λ · W ====================
  function little(o){
    var lam = o.lambda === undefined || o.lambda === '' ? null : num(o.lambda);
    var W   = o.W === undefined || o.W === '' ? null : num(o.W);
    var L   = o.L === undefined || o.L === '' ? null : num(o.L);
    var known = 0;
    if (lam !== null && ok(lam)) known++; else lam = null;
    if (W !== null && ok(W)) known++; else W = null;
    if (L !== null && ok(L)) known++; else L = null;
    if (known < 2) return {error:'Little 定律需要 λ / W / L 中的任意两个'};
    if (lam === null) { if (W <= 0) return {error:'W 必须大于 0'}; lam = L / W; }
    else if (W === null) { if (lam <= 0) return {error:'λ 必须大于 0'}; W = L / lam; }
    else L = lam * W;
    return {error:null, lambda:lam, W:W, L:L,
            note:'L = λ × W：系统中平均在途请求数 = 到达率 × 平均停留时间'};
  }

  // ==================== M/M/1 ====================
  function mm1(lambda, mu){
    var lam = num(lambda), m = num(mu);
    if (!ok(lam) || lam <= 0) return {error:'到达率 λ 必须大于 0'};
    if (!ok(m) || m <= 0) return {error:'服务率 μ 必须大于 0'};
    var rho = lam / m;
    if (rho >= 1) return {error:'系统不稳定：ρ = λ/μ = ' + rho.toFixed(3) + ' ≥ 1，队列会无限增长', rho:rho, stable:false};
    var L = rho / (1 - rho), Lq = rho * rho / (1 - rho);
    var W = 1 / (m - lam), Wq = rho / (m - lam);
    return {
      error:null, stable:true, model:'M/M/1', lambda:lam, mu:m, c:1,
      rho:rho, utilizationPct:rho * 100,
      L:L, Lq:Lq, W:W, Wq:Wq,
      serviceTime:1 / m, P0:1 - rho,
      waitProbability:rho,
      pn:function(n){ return (1 - rho) * Math.pow(rho, n); },
      waitPercentile:function(p){
        if (p <= 0) return 0;
        if (p >= 1) return Infinity;
        return Math.log(1 / (1 - p)) / (m - lam);
      }
    };
  }

  // ==================== Erlang B（呼损系统，无排队）====================
  function erlangB(a, c){
    var A = num(a), C = num(c);
    if (!ok(A) || A < 0) return NaN;
    if (!ok(C) || C < 0 || Math.floor(C) !== C) return NaN;
    var B = 1;
    for (var n = 1; n <= C; n++) B = (A * B) / (n + A * B);
    return B;
  }

  // ==================== Erlang C（M/M/c 等待概率）====================
  function erlangC(a, c){
    var A = num(a), C = num(c);
    if (!ok(A) || A < 0) return NaN;
    if (!ok(C) || C < 1 || Math.floor(C) !== C) return NaN;
    if (A >= C) return 1;
    var term = 1, sum = 1;
    for (var n = 1; n < C; n++){ term = term * A / n; sum += term; }
    var last = term * A / C;
    var rho = A / C;
    var top = last / (1 - rho);
    return top / (sum + top);
  }

  // ==================== M/M/c ====================
  function mmc(lambda, mu, c){
    var lam = num(lambda), m = num(mu), C = num(c);
    if (!ok(lam) || lam <= 0) return {error:'到达率 λ 必须大于 0'};
    if (!ok(m) || m <= 0) return {error:'服务率 μ 必须大于 0'};
    if (!ok(C) || C < 1 || Math.floor(C) !== C) return {error:'服务台数 c 必须是 ≥1 的整数'};
    if (C > 10000) return {error:'服务台数上限 10000'};
    var a = lam / m, rho = a / C;
    if (rho >= 1) return {error:'系统不稳定：ρ = λ/(c·μ) = ' + rho.toFixed(3) + ' ≥ 1，队列会无限增长',
                          rho:rho, stable:false, offeredLoad:a};
    var Pw = erlangC(a, C);
    var Lq = Pw * rho / (1 - rho);
    var Wq = Lq / lam;
    var W = Wq + 1 / m;
    var L = lam * W;
    var Pb = erlangB(a, C);
    return {
      error:null, stable:true, model:'M/M/' + C, lambda:lam, mu:m, c:C,
      offeredLoad:a, rho:rho, utilizationPct:rho * 100,
      waitProbability:Pw, blockProbability:Pb,
      Lq:Lq, L:L, Wq:Wq, W:W, serviceTime:1 / m,
      queueDelayRatio:(Wq * m),
      waitPercentile:function(p){
        if (p <= 0) return 0;
        if (p >= 1) return Infinity;
        if (Pw <= (1 - p)) return 0;
        return Math.log(Pw / (1 - p)) / (C * m - lam);
      }
    };
  }

  // ==================== 容量规划：满足目标排队延迟的最小服务台数 ====================
  function capacityFor(lambda, mu, targetWq, maxC){
    var lam = num(lambda), m = num(mu), tw = num(targetWq);
    if (!ok(lam) || lam <= 0) return {error:'到达率 λ 必须大于 0'};
    if (!ok(m) || m <= 0) return {error:'服务率 μ 必须大于 0'};
    if (!ok(tw) || tw <= 0) return {error:'目标排队延迟必须大于 0：M/M/c 的排队延迟恒为正数，只能无限逼近而无法真正等于 0'};
    var cap = ok(num(maxC)) && num(maxC) > 0 ? Math.floor(num(maxC)) : 2000;
    var start = Math.floor(lam / m) + 1;
    for (var c = start; c <= cap; c++){
      var r = mmc(lam, m, c);
      if (r.error) continue;
      if (r.Wq <= tw){
        return {error:null, c:c, Wq:r.Wq, W:r.W, rho:r.rho, utilizationPct:r.utilizationPct,
                waitProbability:r.waitProbability, minStable:start};
      }
    }
    return {error:'在 ' + cap + ' 个服务台以内无法满足目标排队延迟'};
  }

  // ==================== 线程池 / 连接池容量（Little 定律实用版）====================
  function threadPool(rps, latencyMs, targetUtil){
    var r = num(rps), lat = num(latencyMs), u = num(targetUtil);
    if (!ok(r) || r <= 0) return {error:'RPS 必须大于 0'};
    if (!ok(lat) || lat <= 0) return {error:'平均延迟必须大于 0'};
    if (!ok(u) || u <= 0 || u > 1) return {error:'目标利用率需落在 (0, 1]'};
    var concurrency = r * lat / 1000;
    var threads = Math.ceil(concurrency / u);
    return {
      error:null, concurrency:concurrency, threads:threads, targetUtil:u,
      maxRpsAtPool:threads * u * 1000 / lat,
      headroomPct:(threads * u - concurrency) * 100 / concurrency,
      note:'并发 = RPS × 延迟（Little 定律），再按目标利用率留出余量'
    };
  }

  // ==================== 利用率-延迟曲线（曲棍球棒）====================
  function curve(mu, c, points){
    var m = num(mu), C = num(c) || 1, n = num(points) || 19;
    var out = [];
    for (var i = 1; i <= n; i++){
      var rho = i / (n + 1);
      var lam = rho * C * m;
      var r = mmc(lam, m, C);
      if (r.error) continue;
      out.push({rho:rho, lambda:lam, Wq:r.Wq, W:r.W, ratio:r.W * m});
    }
    return out;
  }

  // 排队延迟超过服务时间 k 倍的“拐点”利用率
  function knee(mu, c, k){
    var m = num(mu), C = num(c) || 1, K = num(k) || 1;
    var lo = 0.01, hi = 0.999, ans = null;
    for (var it = 0; it < 60; it++){
      var mid = (lo + hi) / 2;
      var r = mmc(mid * C * m, m, C);
      if (r.error){ hi = mid; continue; }
      if (r.Wq * m >= K){ ans = mid; hi = mid; } else lo = mid;
    }
    return {rho:ans === null ? 1 : ans, k:K};
  }

  // ==================== 通用可扩展性定律 USL ====================
  function usl(alpha, beta, n){
    var a = num(alpha), b = num(beta), N = num(n);
    if (!ok(a) || a < 0) return {error:'争用系数 α 不能为负'};
    if (!ok(b) || b < 0) return {error:'一致性系数 β 不能为负'};
    if (!ok(N) || N < 1) return {error:'并发度 N 必须 ≥ 1'};
    var speedup = N / (1 + a * (N - 1) + b * N * (N - 1));
    return {error:null, N:N, speedup:speedup, efficiency:speedup / N};
  }
  function uslPeak(alpha, beta){
    var a = num(alpha), b = num(beta);
    if (!ok(a) || a < 0) return {error:'争用系数 α 不能为负'};
    if (!ok(b) || b <= 0) return {error:'β = 0 时不存在峰值（吞吐趋近 1/α 的上限）'};
    var n = Math.sqrt((1 - a) / b);
    return {error:null, peakN:n, peakSpeedup:usl(a, b, n).speedup};
  }

  function analyze(lambda, mu, c){
    var r = mmc(lambda, mu, c);
    if (r.error) return {error:r.error, rho:r.rho, stable:false};
    return {
      error:null, mmc:r,
      p50:r.waitPercentile(0.5), p95:r.waitPercentile(0.95), p99:r.waitPercentile(0.99),
      little:little({lambda:r.lambda, W:r.W}),
      knee2:knee(r.mu, r.c, 1),
      curve:curve(r.mu, r.c, 9),
      single:(r.c === 1 ? null : mm1(r.lambda, r.mu * r.c))
    };
  }

  var api = {little:little, mm1:mm1, mmc:mmc, erlangB:erlangB, erlangC:erlangC,
             capacityFor:capacityFor, threadPool:threadPool, curve:curve, knee:knee,
             usl:usl, uslPeak:uslPeak, analyze:analyze};
  if (typeof window !== 'undefined'){ window.__PURE__ = api; }
  if (typeof module !== 'undefined' && module.exports){ module.exports = {QueueForgePure:QueueForgePure}; }
  return api;
}
